```

Output:

```
93:	const isLoggedIn = !! req.cookies.wordpress_logged_in;
434:					res.clearCookie( 'wordpress_logged_in', {
816:		if ( ! config.isEnabled( 'wpcom-user-bootstrap' ) || ! req.cookies.wordpress_logged_in ) {
842:				res.clearCookie( 'wordpress_logged_in', {
```

The server checks the `wordpress_logged_in` cookie in `client/server/pages/index.js` (lines 90-103):

```javascript
function setupLoggedInContext( req, res, next ) {
    const isSupportSession = !! req.get( 'x-support-session' ) || !! req.cookies.support_session_id;
    const disableHelpCenterAutoOpen = isSupportSession || !! req.cookies.ssp;
    const isLoggedIn = !! req.cookies.wordpress_logged_in;

    req.context = {
        ...req.context,
        isSupportSession,
        disableHelpCenterAutoOpen,
        isLoggedIn,
    };

    next();
}
```

